import { useEffect, useRef } from 'react';

import { useLoading } from '@proton/hooks';
import { SORT_DIRECTION } from '@proton/shared/lib/constants';

import { sendErrorReport } from '../../utils/errorHandling';
import { useLinksListing } from '../_links';
import { useUserSettings } from '../_settings';
import { useDefaultShare } from '../_shares';
import { useAbortSignal, useMemoArrayNoMatterTheOrder, useSortingWithDefault } from './utils';
import type { SortField } from './utils/useSorting';

const DEFAULT_SORT = {
    sortField: 'name' as SortField,
    sortOrder: SORT_DIRECTION.ASC,
};

/**
 * useTrashView provides data for trash view (file browser of trash).
 */
export default function useTrashView() {
    const abortSignal = useAbortSignal();
    const { getDefaultShare } = useDefaultShare();
    const [isLoading, withLoading] = useLoading(true);
    const volumeId = useRef<string>();

    const linksListing = useLinksListing();
    const { links: trashedLinks, isDecrypting } = linksListing.getCachedTrashed(abortSignal, volumeId.current);
    const cachedTrashedLinks = useMemoArrayNoMatterTheOrder(trashedLinks);

    const { layout } = useUserSettings();
    const { sortedList, sortParams, setSorting } = useSortingWithDefault(cachedTrashedLinks, DEFAULT_SORT);

    const loadTrashListing = async (signal: AbortSignal) => {
        const defaultShare = await getDefaultShare(signal);
        volumeId.current = defaultShare.volumeId;
        await linksListing.loadTrashedLinks(signal, defaultShare.volumeId);
    };

    useEffect(() => {
        const ac = new AbortController();
        void withLoading(loadTrashListing(ac.signal)).catch(sendErrorReport);
        return () => {
            ac.abort();
        };
    }, []);

    return {
        layout,
        items: sortedList,
        sortParams,
        setSorting,
        isLoading: isLoading || isDecrypting,
    };
}
import type { FC, ReactNode } from 'react';
import { createContext, useContext, useEffect, useState } from 'react';

import { useDrivePlan } from '@proton/components/hooks/drive';
import { queryDeletePhotosShare, queryPhotos } from '@proton/shared/lib/api/drive/photos';
import type { Photo as PhotoPayload } from '@proton/shared/lib/interfaces/drive/photos';

import { photoPayloadToPhotos, useDebouncedRequest } from '../_api';
import { useUserSettings } from '../_settings';
import type { ShareWithKey } from '../_shares';
import { useDefaultShare } from '../_shares';
import type { Photo } from './interface';

export const PhotosContext = createContext<{
    shareId?: string;
    linkId?: string;
    volumeId?: string;
    showPhotosSection: boolean;
    isLoading: boolean;
    photos: Photo[];
    loadPhotos: (abortSignal: AbortSignal, volumeId: string) => void;
    removePhotosFromCache: (linkIds: string[]) => void;
    deletePhotosShare: (volumeId: string, shareId: string) => Promise<void>;
} | null>(null);

export const PhotosProvider: FC<{ children: ReactNode }> = ({ children }) => {
    const [photosShare, setPhotosShare] = useState<ShareWithKey>();
    const [share, setShare] = useState<ShareWithKey>();
    const { getDefaultShare, getDefaultPhotosShare } = useDefaultShare();

    const request = useDebouncedRequest();
    const [photosLoading, setIsPhotosLoading] = useState<boolean>(false);

    const [photos, setPhotos] = useState<Photo[]>([]);

    const { isB2B } = useDrivePlan();
    const { b2bPhotosEnabled } = useUserSettings();

    const showPhotosSection = isB2B
        ? // B2B depends on user setting, kill switch disables it
          b2bPhotosEnabled
        : // Other plans should always show it
          true;

    useEffect(() => {
        void Promise.all([getDefaultShare(), getDefaultPhotosShare()]).then(([defaultShare, defaultPhotosShare]) => {
            setShare(defaultShare);
            setPhotosShare(defaultPhotosShare);
        });
    }, []);

    const loadPhotos = async (abortSignal: AbortSignal, volumeId: string) => {
        const photoCall = async (lastLinkId?: string) => {
            const { Photos, Code } = await request<{ Photos: PhotoPayload[]; Code: number }>(
                queryPhotos(volumeId, {
                    PreviousPageLastLinkID: lastLinkId,
                }),
                abortSignal
            );
            if (Code === 1000 && !!Photos.length) {
                void Promise.resolve();
                const photosData = Photos.map(photoPayloadToPhotos);
                setPhotos((prevPhotos) => [...prevPhotos, ...photosData]);
                void photoCall(photosData[photosData.length - 1].linkId);
            } else {
                setIsPhotosLoading(false);
            }
        };

        setIsPhotosLoading(true);
        void photoCall();
    };

    const removePhotosFromCache = (linkIds: string[]) => {
        setPhotos((prevPhotos) => {
            return prevPhotos.filter((photo) => !linkIds.includes(photo.linkId));
        });
    };

    const deletePhotosShare = async (volumeId: string, shareId: string): Promise<void> => {
        await request(queryDeletePhotosShare(volumeId, shareId));
    };

    if (!share) {
        return <PhotosContext.Provider value={null}>{children}</PhotosContext.Provider>;
    }

    return (
        <PhotosContext.Provider
            value={{
                shareId: photosShare?.shareId,
                linkId: photosShare?.rootLinkId,
                volumeId: photosShare?.volumeId,
                showPhotosSection,
                isLoading: (!share && !photosShare) || photosLoading,
                photos,
                loadPhotos,
                removePhotosFromCache,
                deletePhotosShare,
            }}
        >
            {children}
        </PhotosContext.Provider>
    );
};

export function usePhotos() {
    const state = useContext(PhotosContext);
    if (!state) {
        throw new Error('Trying to use uninitialized PhotosProvider');
    }
    return state;
}

import type { VERIFICATION_STATUS } from '@proton/crypto';

import type { Photo } from '../_photos';
import type { ThumbnailType } from '../_uploads/media';

/**
 * Link should not be used directly. It is general set of attributes
 * commont for both EncryptedLink and DecryptedLink.
 */
interface Link {
    linkId: string;
    parentLinkId: string;
    isFile: boolean;
    name: string;
    mimeType: string;
    hash: string;
    size: number;
    createTime: number;
    // metaDataModifyTime represents time when the meta data of the link were
    // modified on the server, such as renaming the link, moving to different
    // folder and so on. Note that renaming is not cousing the change of modify
    // time in regular file system. The "real" modify is encrypted in XAttr
    // which is then available in fileModifyTime of DecryptedLink.
    metaDataModifyTime: number;
    trashed: number | null;
    // trashedByParent is set only by internal state in case when parent is
    // trashed which needs to trash also all children as well.
    // Child items need to be trashed so they do not pop up anywhere, for
    // example on shared links page, but at the same time childs of trashed
    // folders should not be listed in trash section to match API behaviour.
    // Note there is also other solution: simply delete childs of trashed
    // folder from the cache, as they should not be needed at all. That is
    // correct, but restoring it quickly back (in case of a mistake) would
    // lead to re-download the whole cache again, and there would be need
    // to re-fetch shared links. So better to keep it around.
    trashedByParent?: boolean;
    hasThumbnail: boolean;
    hasHdThumbnail?: boolean;
    isShared: boolean;
    // Note that shareId is ID of the share, that is pointer of what is shared
    // with someone else. Link can be part of many shares; for example part of
    // user's default share and of shared folder with someone else.
    // Don't use this ID on places where the top/default share should be used.
    // The current share context needs to be always passed explicitely, never
    // used from the link itself.
    shareId?: string;
    // Links associated with Shared URLs don't have share id
    rootShareId: string;
    shareUrl?: LinkShareUrl;
    sharingDetails?: LinkSharingDetails;
    activeRevision?: {
        id: string;
        size: number;
        // Address used for signature checks of blocks and xattributes.
        signatureAddress: string;
        // Thumbnails URL is not part of all requests, because that would be
        // too heavy for API. For example, events do not include it.
        thumbnail?: {
            bareUrl: string;
            token: string;
        };
        thumbnails?: {
            id: string;
            size: number;
            type: ThumbnailType;
            hash: string;
        }[];
        photo?: Photo;
    };
    signatureAddress?: string; // Addresss used for key signatures.
    nameSignatureAddress?: string; // Address used for name signature.
    // If there is no issue, the value should be undefined.
    signatureIssues?: SignatureIssues;
    volumeId: string;
}

export interface LinkShareUrl {
    id: string;
    token: string;
    isExpired: boolean;
    createTime: number;
    expireTime: number | null;
    // numAccesses is not part of API requests, because that would be too
    // heavy for API. This number needs to be loaded explicitely with route
    // to get info about share URL.
    numAccesses?: number;
}

export interface LinkSharingDetails {
    shareUrl?: LinkShareUrl;
    shareId: string;
}

export type SignatureIssues = {
    // Key represents where the issue originated, e.g., passphrase, hash, name
    // xattributes, block, and so on.
    [day in SignatureIssueLocation]?: VERIFICATION_STATUS;
};

export type SignatureIssueLocation =
    | 'passphrase'
    | 'hash'
    | 'name'
    | 'xattrs'
    | 'contentKeyPacket'
    | 'blocks'
    | 'thumbnail'
    | 'manifest';

export interface EncryptedLink extends Link {
    nodeKey: string;
    nodePassphrase: string;
    nodePassphraseSignature?: string;
    nodeHashKey?: string;
    contentKeyPacket?: string;
    contentKeyPacketSignature?: string;
    xAttr: string;
}

export interface DecryptedLink extends Link {
    // name in DecryptedLink is the decrypted part, but we need to keep also
    // encryptedName for renaming procedure (to generate new sessionKey).
    encryptedName: string;
    // See metaDataModifyTime of Link.
    fileModifyTime: number;
    // isLocked is set to true when file is being manipulated, such as moved
    // to different location. When link is locked, it should not be allowed
    // to do anything else with the link (until the operation is done).
    isLocked?: boolean;
    // isStale is indicating whether link needs to be re-decrypted due to
    // server-side update. By default, we don't want to automatically decrypt
    // everything, also, we don't want to simply remove stale link from cache
    // to not cause GUI blinks. App should re-decrypt link on background next
    // time link should be displayed.
    isStale?: boolean;
    // cachedThumbnailUrl is computed URL to cached image. This is not part
    // of any request and not filled automatically. To get this value, use
    // `loadLinkThumbnail` from `useDrive`.
    cachedThumbnailUrl?: string;
    originalSize?: number;
    // In case of image it might contain dimensions stored in XAttributes.
    originalDimensions?: {
        width: number;
        height: number;
    };
